                            || Object.keys(assetPositionOverrides).find(k => toAssetStem(k) === stem);
                        if (hitKey) ov = serverPositions[hitKey] || serverDefaults[hitKey] || assetPositionOverrides[hitKey];
                    }

                    if (!ov) continue;
