            background-size:
                9px 4px, 4px 9px,
                9px 4px, 4px 9px,
                9px 4px, 4px 9px,
                9px 4px, 4px 9px;
            background-position:
                left top, left top,
                right top, right top,
                left bottom, left bottom,
                right bottom, right bottom;
